import"./policy_test_row.js";import{CustomElement}from"chrome://resources/js/custom_element.js";import{getTemplate}from"./policy_test_table.html.js";export class PolicyTestTableElement extends CustomElement{static get template(){return getTemplate()}constructor(){super();this.getRequiredElement("#add-policy-btn").addEventListener("click",this.addEmptyRow.bind(this))}clearRows(){const table=this.getRequiredElement(".table");while(table.childElementCount>1){table.removeChild(table.lastChild)}}addEmptyRow(){const newRow=document.createElement("policy-test-row");const rows=this.shadowRoot.querySelectorAll("policy-test-row");if(rows.length>0){const lastRow=rows[rows.length-1];const attributesToCopy=[".source",".scope",".level",".preset"];attributesToCopy.forEach((attribute=>{const currSelectElement=newRow.getRequiredElement(attribute);const prevSelectElement=lastRow.getRequiredElement(attribute);currSelectElement.value=prevSelectElement.value;currSelectElement.disabled=prevSelectElement.disabled}))}this.getRequiredElement(".table").appendChild(newRow)}addRow(initialValues){const row=this.getRequiredElement(".table").appendChild(document.createElement("policy-test-row"));row.setInitialValues(initialValues)}getTestPoliciesJsonString(){const policyRowArray=Array.from(this.shadowRoot.querySelectorAll("policy-test-row"));const policyInfoArray=policyRowArray.map((row=>({name:row.getPolicyName(),source:Number.parseInt(row.getPolicyAttribute("source")),scope:Number.parseInt(row.getPolicyAttribute("scope")),level:Number.parseInt(row.getPolicyAttribute("level")),value:row.getPolicyValue()})));const rowHasError=row=>row.getErrorState();if(policyRowArray.some(rowHasError)){return""}return JSON.stringify(policyInfoArray)}}customElements.define("policy-test-table",PolicyTestTableElement);